"""Versioned OpenUI contract generated by the Portal registry."""

import hashlib
import json
import re
from functools import cache
from pathlib import Path

FORMAT = "openui"
CATALOG_VERSION = 2
CONTRACT_DIR = Path(__file__).parent
_NAME = re.compile(r"[A-Za-z_][A-Za-z0-9_]*\Z")


def load_contract(directory: Path = CONTRACT_DIR) -> tuple[dict, str, str]:
    catalog = json.loads((directory / "catalog-v2.json").read_bytes())
    if not isinstance(catalog, dict) or catalog.get("format") != FORMAT or catalog.get("version") != CATALOG_VERSION:
        raise ValueError("unsupported GenUI catalog")
    texts = []
    for kind in ("index", "guide"):
        data = (directory / f"openui-v2.{kind}.md").read_bytes()
        if hashlib.sha256(data).hexdigest() != catalog.get(f"{kind}_sha256"):
            raise ValueError(f"GenUI {kind} sha256 mismatch")
        texts.append(data.decode("utf-8"))
    groups, components = catalog.get("groups"), catalog.get("components")
    if not isinstance(groups, list) or not isinstance(components, list) or not components:
        raise ValueError("invalid GenUI components or groups")
    names = []
    for item in components:
        if not isinstance(item, dict) or not isinstance(item.get("name"), str) or not _NAME.fullmatch(item["name"]):
            raise ValueError("invalid GenUI component name")
        names.append(item["name"])
        if not isinstance(item.get("doc"), str) or not item["doc"].strip() or not isinstance(item.get("needs"), list):
            raise ValueError("invalid GenUI component documentation")
    if len(set(names)) != len(names):
        raise ValueError("duplicate GenUI component name")
    group_names, grouped = set(), []
    for group in groups:
        if (
            not isinstance(group, dict)
            or not isinstance(group.get("name"), str)
            or not group["name"]
            or group["name"] in group_names
            or not isinstance(group.get("components"), list)
        ):
            raise ValueError("invalid GenUI group")
        group_names.add(group["name"])
        for name in group["components"]:
            if (
                not isinstance(name, str)
                or name not in names
                or next(c for c in components if c["name"] == name).get("group") != group["name"]
            ):
                raise ValueError("invalid GenUI group component")
            grouped.append(name)
    if len(grouped) != len(names) or set(grouped) != set(names):
        raise ValueError("invalid GenUI group membership")
    for item in components:
        if any(not isinstance(name, str) or name not in names for name in item["needs"]):
            raise ValueError("invalid GenUI dependency")
    return catalog, *texts


@cache
def _loaded() -> tuple[dict, str, str]:
    return load_contract()


@cache
def component_names() -> frozenset[str]:
    return frozenset(c["name"] for c in _loaded()[0]["components"])


def _filter(text: str, html_enabled: bool) -> str:
    return text if html_enabled else "\n".join(line for line in text.splitlines() if "HtmlArtifact" not in line) + "\n"


def index_for(html_enabled: bool) -> str:
    return _filter(_loaded()[1], html_enabled)


def guide_for(html_enabled: bool) -> str:
    return _filter(_loaded()[2], html_enabled)


def component_docs_for(names: list[str], html_enabled: bool) -> tuple[dict[str, str], list[str]]:
    components = _loaded()[0]["components"]
    available = {c["name"]: c for c in components if html_enabled or c["name"] != "HtmlArtifact"}
    selected, unknown = set(), []

    def include(name):
        if name not in available:
            if name not in unknown:
                unknown.append(name)
        elif name not in selected:
            selected.add(name)
            for dependency in available[name]["needs"]:
                include(dependency)

    for name in names:
        include(name)
    return {c["name"]: c["doc"] for c in components if c["name"] in selected}, unknown


def docs_for(names: list[str], html_enabled: bool) -> tuple[str, list[str]]:
    documents, unknown = component_docs_for(names, html_enabled)
    return "\n\n".join(documents.values()), unknown


def full_prompt(html_enabled: bool) -> str:
    docs, _ = docs_for([c["name"] for c in _loaded()[0]["components"]], html_enabled)
    return "\n\n".join((index_for(html_enabled), guide_for(html_enabled), docs))
